parameters.jsCode:
// Compare links between the API results and the spreadsheet to remove duplicate jobs
const existingLinks = new Set(
  $('Load sheetJob').all().map(item => item.json.applicationLink)
);
return $input.all().filter(item => !existingLinks.has(item.json.applicationLink));

for (const item of $input.all()) {
  const html = item.json.description;
  const result = html
    // Convert <br> to a newline
    .replace(/<br\s*\/?>/gi, '\n')
    // Remove all tags except <a>
    .replace(/<(?!\/?a\b)[^>]+>/gi, '');
  item.json.description = result;
}

return $input.all();

