Jobs:
{{ JSON.stringify($input.all(), null, 2) }}

textOptions.schema:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "results": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string", "description": "The ID of each input job." },
          "skills": { "type": "array", "items": { "type": "string" }, "description": "1 to 10 important skills or keywords extracted from the job description." },
          "jobFit": { "type": "integer", "minimum": 1, "maximum": 5, "description": "The degree to which the job description matches the user's profile. 1 = the job description does not match the user's profile at all ~ 5 = matches very well." },
          "jobFitReason": { "type": "string", "description": "The reason for the jobFit score." },
          "preferencesMatch": { "type": "integer", "minimum": 1, "maximum": 5, "description": "The degree to which the job description matches the user's preferences." },
          "preferencesMatchReason": { "type": "string", "description": "The reason for the preferencesMatch score." }
        },
        "required": ["id", "skills", "jobFit", "jobFitReason", "preferencesMatch", "preferencesMatchReason"]
      }
    }
  },
  "required": ["results"]
}

parameters.jsCode:
const text = $input.first().json.output[0].content[0].text;
const result = {};

for (const key in text) {
  const value = text[key];
  // ignore parameter whose value is null or false
  if (value === null || value === false) {
    continue;
  }
  result[key] = value;
}

return [{ json: result }];
